-- Look and feel
--
-- Border and background colours are not here: colours.lua is generated by
-- matugen from the wallpaper and overrides them, and it is required last.

-- How things move, from the shell's own setting (Settings, Appearance,
-- Motion: `animations`, `reduceMotion` and `animationSpeed` in
-- ~/.config/vela/shell.json), so windows move at the pace the shell does.
-- The shell reloads Hyprland when it changes. Read with patterns -- Lua has
-- no JSON parser -- and anything missing or out of range is the default.
local motion = { on = true, reduced = false, speed = 1 }
do
    local dir = os.getenv("XDG_CONFIG_HOME") or ((os.getenv("HOME") or "") .. "/.config")
    local file = io.open(dir .. "/vela/shell.json", "r")
    if file then
        local text = file:read("*a") or ""
        file:close()
        local speed = tonumber(text:match('"animationSpeed"%s*:%s*([%d%.]+)'))
        if speed and speed >= 0.25 and speed <= 4 then
            motion.speed = speed
        end
        motion.on = text:match('"animations"%s*:%s*false') == nil
        motion.reduced = text:match('"reduceMotion"%s*:%s*true') ~= nil
    end
end

-- A duration at that speed: the design's, in tenths of a second, divided.
local function at(ds)
    return ds / motion.speed
end

-- Under reduced motion what slides fades instead, as the shell's own
-- surfaces do.
local function style(moving)
    return motion.reduced and "fade" or moving
end

hl.config({
