-- The shell's motion (docs/motion.md, `Appearance.anim` in the quickshell
-- config), so a window and a panel opening beside it move alike. Speeds are
-- in tenths of a second: 5 is the shell's `morph` and `travel`, 3.5 its
-- `arrive`, 2 its `depart` -- each divided by the speed chosen, like the
-- shell's (`at`, above).
--
--   emphasised  a surface changing size or place -- a window opening, moving,
--               a workspace sliding in -- fast out of the gate, settling late
--   rise        something arriving: fades and layers coming in
--   leave       something going: slow to start, quickest as it disappears
--   standard    small state changes: a border's colour
hl.curve("emphasised", { type = "bezier", points = { { 0.3, 0.9 }, { 0.2, 1 } } })
hl.curve("rise", { type = "bezier", points = { { 0.2, 0.9 }, { 0.2, 1 } } })
hl.curve("leave", { type = "bezier", points = { { 0.3, 0 }, { 0.8, 0.15 } } })
hl.curve("standard", { type = "bezier", points = { { 0.2, 0 }, { 0, 1 } } })

hl.animation({ leaf = "windowsIn", enabled = true, speed = at(5), bezier = "emphasised", style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = at(2), bezier = "leave", style = "popin 87%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = at(5), bezier = "emphasised" })
hl.animation({ leaf = "border", enabled = true, speed = at(4), bezier = "standard" })
hl.animation({ leaf = "borderangle", enabled = true, speed = at(20), bezier = "standard" })
hl.animation({ leaf = "fadeIn", enabled = true, speed = at(3.5), bezier = "rise" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = at(2), bezier = "leave" })
hl.animation({ leaf = "fadeSwitch", enabled = true, speed = at(3.5), bezier = "standard" })
hl.animation({ leaf = "fadeShadow", enabled = true, speed = at(3.5), bezier = "standard" })
hl.animation({ leaf = "fadeDim", enabled = true, speed = at(3.5), bezier = "standard" })
-- Other programs' layer surfaces (fuzzel, anything third-party). The shell's
-- own are `no_anim` in rules.lua, because it animates them itself.
hl.animation({ leaf = "layersIn", enabled = true, speed = at(3.5), bezier = "rise", style = style("slide") })
hl.animation({ leaf = "layersOut", enabled = true, speed = at(2), bezier = "leave", style = style("slide") })
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = at(3.5), bezier = "rise" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = at(2), bezier = "leave" })
hl.animation({ leaf = "workspaces", enabled = true, speed = at(5), bezier = "emphasised", style = style("slide") })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = at(5), bezier = "emphasised", style = style("slidevert") })

-- Three-finger horizontal swipe changes workspace. Declared here rather than
-- in input.lua because `gesture` is an action, not an input setting.
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })
